#define _GNU_SOURCE

#include <ctype.h>
#include <dlfcn.h>
#include <fcntl.h>
#include <stddef.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

static int is_numeric_proc_exe(const char *path) {
    const char prefix[] = "/proc/";
    const char suffix[] = "/exe";
    const char *cursor;

    if (path == NULL || strncmp(path, prefix, sizeof(prefix) - 1) != 0) {
        return 0;
    }
    cursor = path + sizeof(prefix) - 1;
    if (!isdigit((unsigned char)*cursor)) {
        return 0;
    }
    while (isdigit((unsigned char)*cursor)) {
        cursor++;
    }
    return strcmp(cursor, suffix) == 0;
}

ssize_t readlink(const char *path, char *buffer, size_t size) {
    static ssize_t (*real_readlink)(const char *, char *, size_t);

    if (real_readlink == NULL) {
        real_readlink = dlsym(RTLD_NEXT, "readlink");
    }
    return real_readlink(
        is_numeric_proc_exe(path) ? "/proc/self/exe" : path,
        buffer,
        size
    );
}

ssize_t readlinkat(
    int directory,
    const char *path,
    char *buffer,
    size_t size
) {
    static ssize_t (*real_readlinkat)(
        int,
        const char *,
        char *,
        size_t
    );

    if (real_readlinkat == NULL) {
        real_readlinkat = dlsym(RTLD_NEXT, "readlinkat");
    }
    if (is_numeric_proc_exe(path)) {
        return real_readlinkat(AT_FDCWD, "/proc/self/exe", buffer, size);
    }
    return real_readlinkat(directory, path, buffer, size);
}

